// A Meta chama este endereço uma vez para confirmar que ele é seu.
// O token abaixo tem que ser IGUAL ao que você digitar em "Verify token" no painel da Meta.
const MEU_TOKEN_DE_VERIFICACAO = 'ideal-agente-2026';

const q = $json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === MEU_TOKEN_DE_VERIFICACAO;
return [{ json: { resposta: ok ? String(q['hub.challenge']) : 'token incorreto' } }];

// ======= PREENCHA AQUI (só uma vez) =======
return [{
  json: {
    SUPABASE_URL: 'https://SEU-PROJETO.supabase.co',
    SUPABASE_SERVICE_KEY: 'COLE_A_CHAVE_SERVICE_ROLE',   // Supabase > Project Settings > API > service_role
    TOKEN_META: 'COLE_O_TOKEN_DA_PAGINA',                 // token de longa duração da Página (veja o guia)
    IG_USER_ID: 'COLE_O_ID_DO_INSTAGRAM',                 // id da conta profissional (instagram_business_account)
    PAGE_ID: 'COLE_O_ID_DA_PAGINA',                       // id da Página do Facebook ligada ao Instagram
    MEU_USUARIO: 'ia.antoniomongelli',
    GRAPH: 'https://graph.facebook.com/v23.0',
  },
}];

// Recebe os comentários do Instagram e responde quem comentou uma palavra-chave (ex.: AGENTE).
const cfg = $('Configuração').first().json;
const helpers = this.helpers;
const corpo = $('Instagram avisa (POST)').first().json.body || {};
const esperar = (ms) => new Promise((r) => setTimeout(r, ms));
const sb = { apikey: cfg.SUPABASE_SERVICE_KEY, Authorization: `Bearer ${cfg.SUPABASE_SERVICE_KEY}`, 'Content-Type': 'application/json' };

async function supa(fn, body = {}) {
  return helpers.httpRequest({ method: 'POST', url: `${cfg.SUPABASE_URL}/rest/v1/rpc/${fn}`, headers: sb, body, json: true });
}
async function graph(caminho, dados) {
  const r = await helpers.httpRequest({
    method: 'POST', url: `${cfg.GRAPH}/${caminho}`, qs: { access_token: cfg.TOKEN_META },
    body: dados, json: true, ignoreHttpStatusErrors: true,
  });
  if (!r || r.error) throw new Error(r?.error?.error_user_msg || r?.error?.message || 'Erro na API da Meta');
  return r;
}
const normalizar = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toUpperCase();

// 1. separa os comentários que chegaram
const comentarios = [];
for (const entry of corpo.entry || []) {
  for (const ch of entry.changes || []) {
    if (ch.field === 'comments' && ch.value && ch.value.id) comentarios.push(ch.value);
  }
}
if (!comentarios.length) return [{ json: { ignorado: 'nenhum comentário no aviso' } }];

// 2. palavras-chave ativas (tabela instagram_palavras)
const palavras = await helpers.httpRequest({
  method: 'GET', url: `${cfg.SUPABASE_URL}/rest/v1/instagram_palavras?ativa=eq.true&select=*`, headers: sb, json: true,
});

const saida = [];
for (const c of comentarios) {
  const autor = c.from || {};
  if (autor.id === cfg.IG_USER_ID || autor.username === cfg.MEU_USUARIO) continue; // não responde a si mesmo

  const texto = normalizar(c.text);
  const p = (palavras || []).find((x) => new RegExp(`(^|[^A-Z0-9])${normalizar(x.palavra)}([^A-Z0-9]|$)`).test(texto));
  if (!p) continue;

  // registra; se já existia, é repetido: não responde de novo
  const novo = await supa('instagram_registrar_comentario', {
    p_comment_id: c.id, p_media_id: c.media?.id || null, p_username: autor.username || null, p_texto: c.text || '', p_palavra: p.palavra,
  });
  if (!novo) continue;

  // 1º o direct, na hora: é o que gera o agendamento do diagnóstico
  let publico = false, direct = false, erro = null;
  try {
    const msg = p.mensagem_direct.replaceAll('{nome}', autor.username ? `@${autor.username}` : '');
    await graph(`${cfg.PAGE_ID}/messages`, { recipient: { comment_id: c.id }, message: { text: msg } });
    direct = true;
  } catch (e) { erro = `direct: ${e.message}`; }

  // 2º a resposta pública (com um respiro curto, pra não parecer robô)
  await esperar(1500 + Math.floor(Math.random() * 2000));
  try {
    const resposta = p.respostas[Math.floor(Math.random() * p.respostas.length)];
    await graph(`${c.id}/replies`, { message: autor.username ? `@${autor.username} ${resposta}` : resposta });
    publico = true;
  } catch (e) { erro = [erro, `público: ${e.message}`].filter(Boolean).join(' | '); }

  await supa('instagram_atualizar_comentario', { p_comment_id: c.id, p_publico: publico, p_direct: direct, p_erro: erro });
  saida.push({ json: { comentario: c.id, usuario: autor.username, palavra: p.palavra, publico, direct, erro } });
}

return saida.length ? saida : [{ json: { ignorado: 'nenhuma palavra-chave' } }];
